/**
 * opencode-qiwei OpenCode 插件模式
 *
 * 注册为 OpenCode 插件，自动处理企微消息
 * 使用方式：在 ~/.config/opencode/opencode.jsonc 中添加
 *   "plugin": ["@neomei/opencode-qiwei"]
 */
import { WSClient } from "@wecom/aibot-node-sdk";
import { ConfigManager } from "./core/config.js";
import { SessionManager } from "./core/session-manager.js";
import { MessageHandler } from "./core/message-handler.js";
import { HookManager } from "./core/hook-manager.js";
import { OpenCodeClient } from "./opencode/client.js";
import { OpenCodeEventHandler } from "./opencode/event-handler.js";
import { isAbsolute } from "node:path";
import { createLogger } from "./core/logger.js";
const log = createLogger("Plugin");
export default function QiweiPlugin(_ctx) {
    let wsClient;
    let eventHandler;
    let cleanup;
    return {
        name: "opencode-qiwei",
        version: "0.2.0",
        async start() {
            try {
                const configManager = new ConfigManager();
                const config = configManager.load();
                const opencode = new OpenCodeClient({ baseUrl: config.opencodeUrl });
                // 初始化 HookManager（魂器集成）
                let hookManager;
                if (config.hooks) {
                    const onSessionCreated = config.hooks.onSessionCreated;
                    const projectDir = onSessionCreated
                        ? (isAbsolute(onSessionCreated) ? onSessionCreated.replace(/[\/]connectors[\/]qiwei[\/]hooks[\/].*$/, "") : process.cwd())
                        : process.cwd();
                    hookManager = new HookManager(config.hooks, projectDir);
                }
                const sessionManager = new SessionManager({
                    hookManager,
                    opencodeUrl: config.opencodeUrl,
                });
                const wsClientOptions = {
                    botId: config.botId,
                    secret: config.secret,
                    reconnectInterval: 2000,
                    maxReconnectAttempts: -1,
                    maxAuthFailureAttempts: config.maxAuthFailureAttempts ?? 5,
                    heartbeatInterval: 30000,
                    requestTimeout: config.requestTimeout ?? 10000,
                };
                if (config.wsUrl) {
                    wsClientOptions.wsUrl = config.wsUrl;
                }
                if (config.scene !== undefined) {
                    wsClientOptions.scene = config.scene;
                }
                if (config.plugVersion) {
                    wsClientOptions.plug_version = config.plugVersion;
                }
                wsClient = new WSClient(wsClientOptions);
                const messageHandler = new MessageHandler(config, sessionManager, wsClient, opencode);
                if (config.streaming) {
                    eventHandler = new OpenCodeEventHandler(sessionManager, messageHandler, config.opencodeUrl, config.autoApprove, opencode, hookManager);
                    opencode.subscribeEvents().then(s => eventHandler.start(s)).catch(err => log.warn('SSE 连接失败，将自动重试', { err }));
                }
                // 消息事件
                wsClient.on("message.text", f => messageHandler.handleMessage(f).catch(e => log.error("text", e)));
                wsClient.on("message.image", f => messageHandler.handleImageMessage(f).catch(e => log.error("image", e)));
                wsClient.on("message.mixed", f => messageHandler.handleMixedMessage(f).catch(e => log.error("mixed", e)));
                wsClient.on("message.voice", f => messageHandler.handleVoiceMessage(f).catch(e => log.error("voice", e)));
                wsClient.on("message.file", f => messageHandler.handleFileMessage(f).catch(e => log.error("file", e)));
                wsClient.on("message.video", f => messageHandler.handleVideoMessage(f).catch(e => log.error("video", e)));
                // 事件回调
                wsClient.on("event.enter_chat", f => messageHandler.handleEnterChat(f).catch(e => log.error("enter", e)));
                wsClient.on("event.template_card_event", f => messageHandler.handleCardEvent(f).catch(e => log.error("card", e)));
                wsClient.on("event.feedback_event", f => {
                    const userid = f.body?.from?.userid;
                    log.info(`💬 用户反馈: ${userid}`);
                });
                wsClient.on("event.disconnected_event", f => {
                    log.warn("🔌 服务端要求断开（可能有多端登录）");
                });
                wsClient.connect();
                log.info("插件已启动");
                cleanup = () => { wsClient?.disconnect(); eventHandler?.stop(); };
            }
            catch (err) {
                log.error("插件启动失败", { err });
            }
        },
        async stop() {
            cleanup?.();
            log.info("插件已停止");
        },
    };
}
